157	// fetchGroupMembers calls the format-specific group endpoint which reliably
158	// includes memberNames: GET /v1/repositories/{format}/group/{name}
159	// Requires nx-repository-admin privilege; falls back to anonymous when credentials fail.
160	//
161	// It returns a settled listing (non-nil, possibly empty) or an error, never a
162	// silent "no members": a 401 or 403 is a *MembersRefusedError, anything else that
163	// goes wrong is returned as it is. The caller caches the first and must not cache
164	// the second (D23).
165	//
166	// The first attempt decides. The anonymous retry (D156) only changes the outcome
167	// by succeeding: whatever it gets otherwise, the account was refused and that is
168	// the actionable fact.
169	func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) ([]GroupMember, error) {
170		if format == "" {
171			format = "docker"
172		}
173		// The format comes from the server: it stays one path segment.
174		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, url.PathEscape(format), repoName)
175		body, err := n.nexusGET(ctx, endpoint, info)
176		if err != nil {
177			firstErr := err
178			// When auth is present but the request fails, retry anonymously.
179			// Some Nexus instances allow anonymous read of the group admin endpoint.
180			// A refused redirect to another origin is not such a failure: the
181			// detection stops there (DEVDESK-412), no silent anonymous retry.
182			if info.Username != "" && info.Password != "" && !errors.Is(err, oci.ErrOffOriginRedirect) {
183				anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
184				body, err = n.nexusGET(ctx, endpoint, anonInfo)
185				if err != nil {
186					log.Printf("INFO [registrymgr/nexus] anonymous retry for %q failed: %v", repoName, err)
187				}
188			}
189			if err != nil {
190				return nil, membersFailure(host, repoName, endpoint, firstErr, info.Username != "" && info.Password != "")
191			}
192		}
193		names, err := parseGroupMembers(body)
194		if err != nil {
195			log.Printf("INFO [registrymgr/nexus] members %q: %v", repoName, err)
196			return nil, fmt.Errorf("reading the members of group %q: %w", repoName, err)
197		}
198		return memberList(info.URL, names), nil
199	}
