201	// membersFailure logs and types the failure of the first attempt on the format
202	// endpoint: a refusal when the manager refused the account, the error itself
203	// otherwise. The returned error holds the group and the status, never the URL.
204	func membersFailure(host, repoName, endpoint string, err error, hasAuth bool) error {
205		if status, ok := refusedStatus(err); ok {
206			log.Printf("INFO [registrymgr/nexus] members refused %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
207			return &MembersRefusedError{Group: repoName, Status: status, Anonymous: !hasAuth, Cause: err}
208		}
209		if errors.Is(err, oci.ErrOffOriginRedirect) {
210			// The advice above is for an account Nexus refused, not for this.
211			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — redirect to another origin refused (the registry URL may need to be the one Nexus serves)", endpoint, err)
212		} else {
213			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v", endpoint, err)
214		}
215		return fmt.Errorf("reading the members of group %q: %w", repoName, err)
216	}
