218	// parseGroupMembers reads the member names of a format-endpoint reply. A document
219	// is a `group` object carrying a `memberNames` key, an empty list included: an
220	// empty body, `null`, `{}` or a group without the key is not one, and reading it
221	// as "no members" would be cached over what was last known.
222	func parseGroupMembers(body []byte) ([]string, error) {
223		if len(bytes.TrimSpace(body)) == 0 {
224			return nil, errEmptyReply
225		}
226		var doc struct {
227			Group *struct {
228				MemberNames []string `json:"memberNames"`
229			} `json:"group"`
230		}
