267	// memberAddress decides how one member of a group is reached, from the URL the
268	// group itself is pulled from.
269	//
270	// A group written as a path prefix — `host/repository/<group>` — is an instance
271	// serving its Docker repositories that way, so its members are reached the same
272	// way: the host, with the member's name in front of the repository. That pair is
273	// consistent by construction, because browse and pull build the same path from
274	// it.
275	//
276	// Anything else is a connector of the group's own — a dedicated port, a
277	// subdomain — and says nothing about a member. Which of those a repository
278	// answers on is a setting on that repository (`docker.httpPort`,
279	// `docker.httpsPort`, `docker.subdomain`), and the endpoint carrying it is
280	// refused to an ordinary pull account. So nothing is claimed: the member is
281	// offered at the group's own address with no prefix, which browses to nothing
282	// visibly rather than pulling to nothing plausibly (§3.18).
283	func memberAddress(dockerURL, memberName string) (url, prefix string) {
284		host, _, err := parseNexusURL(dockerURL)
285		if err != nil {
286			return dockerURL, ""
287		}
288		// parseNexusURL supplies https:// for a URL written without a scheme. The
289		// group's own spelling is what the rest of the application is keyed on, so
290		// it is kept rather than normalised here.
291		if !strings.Contains(strings.ToLower(dockerURL), "://") {
292			host = strings.TrimPrefix(host, "https://")
293		}
294		return host, memberName
295	}
