297	// nexusGET performs an authenticated GET and returns the response body. A status
298	// other than 200 is a *oci.StatusError from the management API: the code only, no
299	// status line, body or header. A context error stays a context error.
300	func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
301		req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
302		if err != nil {
303			return nil, err
304		}
305		if info.Username != "" && info.Password != "" {
306			req.SetBasicAuth(info.Username, info.Password)
307		}
308		resp, err := nexusHTTPClient.Do(req)
309		if err != nil {
310			// A refused redirect comes back without the URL it pointed to, which
311			// may be signed.
312			return nil, oci.StripRedirectTarget(err)
313		}
314		defer func() { _ = resp.Body.Close() }()
315		if resp.StatusCode != http.StatusOK {
316			return nil, &oci.StatusError{Code: resp.StatusCode, Source: oci.SourceManagementAPI}
317		}
318		body, err := oci.ReadAllLimited(resp.Body, maxNexusResponse)
319		if err != nil {
320			// Which error net/http gives a body cut by a cancel varies: report the
321			// context's own.
322			if ctxErr := ctx.Err(); ctxErr != nil {
323				return nil, fmt.Errorf("read Nexus response: %w", ctxErr)
324			}
325			return nil, fmt.Errorf("read Nexus response: %w", err)
326		}
327		return body, nil
328	}
