330	// parseNexusURL extracts the scheme+host and repository name from a Nexus URL.
331	// e.g. "https://nexus.example.com/repository/docker-group" → ("https://nexus.example.com", "docker-group")
332	func parseNexusURL(registryURL string) (host, repoName string, err error) {
333		raw := registryURL
334		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
335			raw = "https://" + raw
336		}
337		u, err := url.Parse(raw)
338		if err != nil {
339			return "", "", err
340		}
341		parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
342		// Expected: ["repository", "<repoName>", ...]
343		if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
344			return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
345		}
346		host = u.Scheme + "://" + u.Host
347		repoName = parts[1]
348		return host, repoName, nil
349	}
