351	// cleanMemberAlias strips common suffixes (-proxy, -hosted, -local) for a friendlier display name.
352	func cleanMemberAlias(name string) string {
353		for _, suffix := range []string{"-proxy", "-hosted", "-local"} {
354			if strings.HasSuffix(name, suffix) {
355				return name[:len(name)-len(suffix)]
356			}
357		}
358		return name
359	}
