52	// DetectGroup calls the Nexus REST API to determine whether the registry points
53	// to a group repository and, if so, returns its member repositories.
54	//
55	// Returns nil, nil when the manager answered and the repository is not a group,
56	// a non-nil empty list for a group it listed with no member, and an error when it
57	// could not be asked or refused to list the members (a *MembersRefusedError,
58	// errors.Is ErrMembersRefused). Those are not the same thing: the caller caches
59	// the settled answers and must not cache an error, or one unreachable minute (or
60	// one refused account) erases what was last known (D23).
61	func (n *NexusDetector) DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) {
62		// Resolve which URL to use for the Nexus API call.
63		apiBase := info.ManagementURL
64		if apiBase == "" {
65			apiBase = info.URL
66		}
67	
68		host, repoName, err := parseNexusURL(apiBase)
69		if err != nil {
70			// Not an error: a URL that is not a Nexus repository path is a settled
71			// answer, not a failure to reach one.
72			// The cause only: a URL that does not parse may hold a password, and
73			// url.Error repeats it whole.
74			var ue *url.Error
75			if errors.As(err, &ue) {
76				err = ue.Err
77			}
78			log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL: %v", err)
79			return nil, nil
80		}
81	
82		hasAuth := info.Username != "" && info.Password != ""
83		log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)
84	
85		// Step 1: generic endpoint — confirms this repo is a group, gets its format,
86		// and may already include memberNames in the attributes field (no admin privilege needed).
87		repoType, repoFormat, members, err := n.fetchRepoMeta(ctx, host, repoName, info)
88		if err != nil {
89			return nil, err
90		}
91		if repoType != "group" {
92			return nil, nil
93		}
94	
95		if len(members) > 0 {
96			log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
97			return members, nil
98		}
99	
100		// Step 2: format-specific endpoint — requires nx-repository-admin privilege
101		// but returns memberNames reliably on Nexus instances that support it.
102		members, err = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
103		if err != nil {
104			return nil, err
105		}
106		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
107		return members, nil
108	}
