144			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errNoRepositoryType)
145		}
146		log.Printf("INFO [registrymgr/nexus] meta %q: type=%q format=%q", repoName, result.Type, result.Format)
